// ---- WIRE & CABLE DATA ----
// Quantity for wires is entered in TOTAL METERS. Each variant is a coil/roll
// of a fixed length; price-per-meter is derived from (roll price / roll length),
// then multiplied by the meters the customer requests.
const WIRE_SIZES = ["1 SQMM", "1.5 SQMM", "2.5 SQMM", "4 SQMM", "6 SQMM"];

type WireVariant = {
  key: string;
  brand: string;
  label: string;
  // Either a single roll length for all sizes, or a per-size map (Standard coil
  // is 300m for 1/1.5/2.5 sqmm but 200m for 4/6 sqmm)
  rollLength: number | { [size: string]: number };
  prices: { [size: string]: number };
};

const WIRE_VARIANTS: WireVariant[] = [
  {
    key: "PRINA_90",
    brand: "PolyCab",
    label: "PolyCab Prina (90m Roll)",
    rollLength: 90,
    prices: { "1 SQMM": 2705, "1.5 SQMM": 3975, "2.5 SQMM": 6335, "4 SQMM": 9715, "6 SQMM": 14610 },
  },
  {
    key: "OPTIMA_90",
    brand: "PolyCab",
    label: "PolyCab Optima+ (90m Roll)",
    rollLength: 90,
    prices: { "1 SQMM": 2790, "1.5 SQMM": 4080, "2.5 SQMM": 6455, "4 SQMM": 9445, "6 SQMM": 14610 },
  },
  {
    key: "STD_LONG",
    brand: "PolyCab",
    label: "PolyCab Standard (Long Coil)",
    rollLength: { "1 SQMM": 300, "1.5 SQMM": 300, "2.5 SQMM": 300, "4 SQMM": 200, "6 SQMM": 200 },
    prices: { "1 SQMM": 11935, "1.5 SQMM": 17490, "2.5 SQMM": 29030, "4 SQMM": 29960, "6 SQMM": 44855 },
  },
];

const getWireRollLength = (variant: WireVariant, size: string): number => {
  return typeof variant.rollLength === "number" ? variant.rollLength : variant.rollLength[size];
};

const getWirePricePerMeter = (variant: WireVariant, size: string): number => {
  const rollLength = getWireRollLength(variant, size);
  const rollPrice = variant.prices[size] || 0;
  return rollLength > 0 ? rollPrice / rollLength : 0;
};

